func (r *EmitResolver) hasVisibleDeclarations(symbol *store.Symbol, shouldComputeAliasToMakeVisible bool) *storeprinter.SymbolAccessibilityResult {
	var aliasesToMakeVisibleSet map[store.NodeKey]store.Node

	var addVisibleAlias func(declaration store.Node, aliasingStatement store.Node)
	if shouldComputeAliasToMakeVisible {
		addVisibleAlias = func(declaration store.Node, aliasingStatement store.Node) {
			r.declarationLinks.Get(declaration.Key()).isVisible = core.TSTrue
			if aliasesToMakeVisibleSet == nil {
				aliasesToMakeVisibleSet = make(map[store.NodeKey]store.Node)
			}
			aliasesToMakeVisibleSet[declaration.Key()] = aliasingStatement
		}
	} else {
		addVisibleAlias = noopAddVisibleAlias
	}

	for _, declaration := range symbol.Declarations {
		if store.IsIdentifier(declaration) {
			continue
		}
		if !r.isDeclarationVisible(declaration) {
			// Mark the unexported alias as visible if its parent is visible
			// because these kind of aliases can be used to name types in declaration file
			anyImportSyntax := getAnyImportSyntax(declaration)
			if !anyImportSyntax.IsNil() &&
				!store.HasSyntacticModifier(anyImportSyntax, ast.ModifierFlagsExport) && // import clause without export
				r.isDeclarationVisible(anyImportSyntax.Parent()) {
				addVisibleAlias(declaration, anyImportSyntax)
				continue
			}
			if store.IsVariableDeclaration(declaration) && store.IsVariableStatement(declaration.Parent().Parent()) &&
				!store.HasSyntacticModifier(declaration.Parent().Parent(), ast.ModifierFlagsExport) && // unexported variable statement
				r.isDeclarationVisible(declaration.Parent().Parent().Parent()) {
				addVisibleAlias(declaration, declaration.Parent().Parent())
				continue
			}
			if store.IsLateVisibilityPaintedStatement(declaration) && // unexported top-level statement
				!store.HasSyntacticModifier(declaration, ast.ModifierFlagsExport) &&
				r.isDeclarationVisible(declaration.Parent()) {
				addVisibleAlias(declaration, declaration)
				continue
			}
			if store.IsBindingElement(declaration) {
				if symbol.Flags&ast.SymbolFlagsAlias != 0 && store.IsInJSFile(declaration) && !declaration.Parent().IsNil() && !declaration.Parent().Parent().IsNil() && // exported import-like top-level JS require statement
					store.IsVariableDeclaration(declaration.Parent().Parent()) &&
					!declaration.Parent().Parent().Parent().Parent().IsNil() && store.IsVariableStatement(declaration.Parent().Parent().Parent().Parent()) &&
					!store.HasSyntacticModifier(declaration.Parent().Parent().Parent().Parent(), ast.ModifierFlagsExport) &&
					!declaration.Parent().Parent().Parent().Parent().Parent().IsNil() && // check if the thing containing the variable statement is visible (ie, the file)
					r.isDeclarationVisible(declaration.Parent().Parent().Parent().Parent().Parent()) {
					addVisibleAlias(declaration, declaration.Parent().Parent().Parent().Parent())
					continue
				}
				if symbol.Flags&ast.SymbolFlagsBlockScopedVariable != 0 {
					rootDeclaration := store.WalkUpBindingElementsAndPatterns(declaration)
					if store.IsParameterDeclaration(rootDeclaration) {
						return nil
					}
					variableStatement := rootDeclaration.Parent().Parent()
					if !store.IsVariableStatement(variableStatement) {
						return nil
					}
					if store.HasSyntacticModifier(variableStatement, ast.ModifierFlagsExport) {
						continue // no alias to add, already exported
					}
					if !r.isDeclarationVisible(variableStatement.Parent()) {
						return nil // not visible
					}
					addVisibleAlias(declaration, variableStatement)
					continue
				}
			}

			// Declaration is not visible
			return nil
		}
	}

	return &storeprinter.SymbolAccessibilityResult{
		Accessibility:        storeprinter.SymbolAccessibilityAccessible,
		AliasesToMakeVisible: slices.Collect(maps.Values(aliasesToMakeVisibleSet)),
	}
}

func (r *EmitResolver) requiresAddingImplicitUndefined(declaration store.Node, symbol *store.Symbol, enclosingDeclaration store.Node) bool {
	// node = r.emitContext.ParseNode(node)
	if !store.IsParseTreeNode(declaration) {
		return false
	}
	switch declaration.Kind() {
	case ast.KindPropertyDeclaration, ast.KindPropertySignature, ast.KindJSDocPropertyTag:
		if symbol == nil {
			symbol = r.checker.getSymbolOfDeclaration(declaration)
		}
		t := r.checker.getTypeOfSymbol(symbol)
		r.checker.mappedSymbolLinks.Has(symbol)
		return (symbol.Flags&ast.SymbolFlagsProperty != 0) && (symbol.Flags&ast.SymbolFlagsOptional != 0) && isOptionalDeclaration(declaration) && r.checker.ReverseMappedSymbolLinks.Has(symbol) && r.checker.ReverseMappedSymbolLinks.Get(symbol).mappedType != nil && containsNonMissingUndefinedType(r.checker, t)
	case ast.KindParameter, ast.KindJSDocParameterTag:
		return r.requiresAddingImplicitUndefinedWorker(declaration, enclosingDeclaration)
	default:
		panic("Node cannot possibly require adding undefined")
	}
}

func (r *EmitResolver) requiresAddingImplicitUndefinedWorker(parameter store.Node, enclosingDeclaration store.Node) bool {
	return (r.isRequiredInitializedParameter(parameter, enclosingDeclaration) || r.isOptionalUninitializedParameterProperty(parameter)) && !r.declaredParameterTypeContainsUndefined(parameter)
}

func (r *EmitResolver) declaredParameterTypeContainsUndefined(parameter store.Node) bool {
	// typeNode := getNonlocalEffectiveTypeAnnotationNode(parameter); // !!! JSDoc Support
	typeNode := parameter.Type()
	if typeNode.IsNil() {
		return false
	}
	t := r.checker.getTypeFromTypeNode(typeNode)
	// allow error type here to avoid confusing errors that the annotation has to contain undefined when it does in cases like this:
	//
	// export function fn(x?: Unresolved | undefined): void {}
	return r.checker.isErrorType(t) || r.checker.containsUndefinedType(t)
}

func (r *EmitResolver) isOptionalUninitializedParameterProperty(parameter store.Node) bool {
	return r.checker.strictNullChecks &&
		r.isOptionalParameter(parameter) &&
		( /*isJSDocParameterTag(parameter) ||*/ parameter.Initializer().IsNil()) && // !!! TODO: JSDoc support
		store.HasSyntacticModifier(parameter, ast.ModifierFlagsParameterPropertyModifier)
}

func (r *EmitResolver) isRequiredInitializedParameter(parameter store.Node, enclosingDeclaration store.Node) bool {
	if !r.checker.strictNullChecks || r.isOptionalParameter(parameter) || /*isJSDocParameterTag(parameter) ||*/ parameter.Initializer().IsNil() { // !!! TODO: JSDoc Support
		return false
	}
	if store.HasSyntacticModifier(parameter, ast.ModifierFlagsParameterPropertyModifier) {
		return !enclosingDeclaration.IsNil() && store.IsFunctionLikeDeclaration(enclosingDeclaration)
	}
	return true
}

